        # Calder writes day first, dd/mm/yyyy; Ardent and Borough both write ISO.
        try:
            return datetime.strptime(raw, "%d/%m/%Y").date()
        except ValueError as exc:
            raise LedgerParseError(f"unreadable Calder date {raw!r}") from exc
